/**
 * saga-voice.js — lookup for the pre-recorded Sonia and Eric saga clips.
 *
 * The clips are ordinary MP3s generated by the authoring tool. The browser
 * never connects to a speech service or loads a model. Each clip is keyed by
 * the same FNV-1a scene hash used for the Piper clips, so a custom name that
 * was not recorded simply has no URL.
 */

import { sagaTextId } from './narration.js?v=20261110-3';

export const SAGA_VOICES = Object.freeze([
  { id: 'sonia', label: 'Sonia', note: 'female, British English' },
  { id: 'eric', label: 'Eric', note: 'male, American English' },
]);

export const SAGA_VOICE_VERSION = '20261110-3';

export function isSagaVoice(voice) {
  return SAGA_VOICES.some((entry) => entry.id === voice);
}

export function sagaVoiceLabel(voice) {
  return SAGA_VOICES.find((entry) => entry.id === voice)?.label || 'Studio';
}

export function sagaVoiceUrl(voice, text) {
  if (!isSagaVoice(voice)) return '';
  const id = sagaTextId(text);
  return id ? `audio/saga/${voice}/${id}.mp3?v=${SAGA_VOICE_VERSION}` : '';
}
